{"CommandLine":"c:\AI-BS\pyppeteer_env\Scripts\python.exe -c "
import os, glob, sqlite3

dbs = glob.glob(r'c:\AI-BS\**\*.db', recursive=True)
for d in dbs:
    if 'node_modules' in d or 'pyppeteer_env' in d or '.git' in d:
        continue
    sz_mb = os.path.getsize(d) / (1024*1024)
    try:
        conn = sqlite3.connect(d)
        tables = [r[0] for r in conn.execute('SELECT name FROM sqlite_master WHERE type=\'table\'').fetchall()]
        conn.close()
        print(f'{os.path.basename(d):<30} | {sz_mb:>6.2f} MB | {tables[:4]}')
    except Exception as e:
        print(f'{os.path.basename(d):<30} | Error: {e}')
